// @ppm--version--1.1

import React, { useEffect, useState } from "react";

type Status = "idle" | "loading" | "loaded" | "error";

type Props = {
  src: string | null;
  alt?: string;
  className?: string;
  /** Element shown while the image is being verified.
   *  Defaults to an inline spinner. Pass `null` to render nothing. */
  loading?: React.ReactNode;
  /** Element shown when src is missing or load fails.
   *  Defaults to null (the image is effectively removed from layout). */
  fallback?: React.ReactNode;
  /** Called when the image fails to load. Useful for removing stale entries
   *  from a parent gallery — e.g. when files.json points at a now-deleted file. */
  onError?: () => void;
};

// Self-verifying image: pre-loads via the browser's image cache, shows a
// spinner while that's in flight, swaps to the real <img> only after it's
// confirmed loadable. On a 404 (or any load failure), it falls back to
// `fallback` and notifies `onError` so a parent can drop the entry.
export default function Image({
  src,
  alt = "",
  className,
  loading,
  fallback = null,
  onError,
}: Props) {
  const [status, setStatus] = useState<Status>(src ? "loading" : "idle");

  useEffect(() => {
    setStatus(src ? "loading" : "idle");
    if (!src) return;

    let cancelled = false;
    const probe = new window.Image();
    probe.onload = () => { if (!cancelled) setStatus("loaded"); };
    probe.onerror = () => {
      if (cancelled) return;
      setStatus("error");
      onError?.();
    };
    probe.src = src;

    return () => {
      cancelled = true;
      probe.onload = null;
      probe.onerror = null;
    };
  }, [src, onError]);

  if (!src || status === "error") return <>{fallback}</>;

  if (status === "loading") {
    return <>{loading === undefined ? <Spinner className={className} /> : loading}</>;
  }

  return <img src={src} alt={alt} className={className} />;
}

function Spinner({ className }: { className?: string }) {
  return (
    <span
      className={className}
      aria-busy="true"
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#f0f0f0",
      }}
    >
      <span
        style={{
          width: 22,
          height: 22,
          border: "2px solid rgba(0,0,0,0.12)",
          borderTopColor: "rgba(0,0,0,0.45)",
          borderRadius: "50%",
          animation: "ppm-image-spin 0.8s linear infinite",
        }}
      />
      <style>{`@keyframes ppm-image-spin { to { transform: rotate(360deg); } }`}</style>
    </span>
  );
}
