// Adds an alpha channel to a hex colour so theme-derived translucent shades
// (glows, soft backgrounds, focus rings) stay in sync with `theme.primary`.
function withAlpha(color: string, alpha: number): string {
  if (color.startsWith("#") && (color.length === 4 || color.length === 7)) {
    const hex = color.length === 4
      ? color.slice(1).split("").map(c => c + c).join("")
      : color.slice(1);
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }
  return color;
}

// Whether a hex colour is dark enough that we should pair it with light
// foreground text. Lets the sidebar auto-pick contrast without needing a
// separate sidebarText theme token.
function isDarkColor(hex: string): boolean {
  const m = hex.match(/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!m) return false;
  let h = m[1];
  if (h.length === 3) h = h.split("").map(c => c + c).join("");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum < 0.55;
}

const SIDEBAR_IS_DARK = isDarkColor(theme.sidebar);

type Img = {
  id: string;
  src: string;            // currently-displayed URL (local blob: while remote is warming up)
  name: string;
  isNew?: boolean;
  isStatic?: boolean;
  pendingUrl?: string;    // the remote webpUrl we're waiting to become reachable
  meta?: Record<string, any>;  // arbitrary metadata (alt, etc.) from files.json
};

