// @ppm--version--1.0



// Canvas-based 200x200 cover thumbnail → JPEG data URL.
//
// Why: Used as the in-upload preview. A blob: URL from URL.createObjectURL
// is perfect during the same session but evaporates on reload. A data URL
// fits in localStorage (~5–15 KB at 200px / 0.8 quality), so a refresh
// mid-upload still shows the user's image in the perception toast.
//
// Lifted from src/pages/dashboard/thumb.tsx so the exact same cover-crop
// geometry is used everywhere.

export async function createThumbnail(
  file: File,
  size = 200,
  quality = 0.8
): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("FileReader failed"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Image decode failed"));
      img.onload = () => {
        try {
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");
          if (!ctx) { reject(new Error("No 2D canvas context")); return; }

          canvas.width = size;
          canvas.height = size;

          const imgRatio = img.width / img.height;
          let drawWidth: number, drawHeight: number, offsetX: number, offsetY: number;

          if (imgRatio > 1) {
            // landscape → crop left/right
            drawHeight = size;
            drawWidth = img.width * (size / img.height);
            offsetX = -(drawWidth - size) / 2;
            offsetY = 0;
          } else {
            // portrait/square → crop top/bottom
            drawWidth = size;
            drawHeight = img.height * (size / img.width);
            offsetX = 0;
            offsetY = -(drawHeight - size) / 2;
          }

          ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
          resolve(canvas.toDataURL("image/jpeg", quality));
        } catch (err) {
          reject(err);
        }
      };
      img.src = String(reader.result ?? "");
    };
    reader.readAsDataURL(file);
  });
}
